# Put a person on hold, or release them (the body says which). Validate before Load so a bad body is a
# 400, not masked by a 404; a person already in that state is refused (400) and writes nothing.
validate:
  class: net.officefloor.hq.app.person.ValidateHold
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.person.SavePerson
  govern: [ transaction ]
  next: audit
# Record the change only once it is saved, so a refused change writes no audit line.
audit:
  class: net.officefloor.hq.app.person.AuditPersonHold
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
# The sheet's people, in the order they were added.
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the hold body, refusing one that does not say whether to hold or release. */
public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<HoldInput> holdOut) throws InvalidPersonException {
        if (request == null || request.held() == null) {
            throw new InvalidPersonException("Say whether to hold or release the person.");
        }
        holdOut.set(new HoldInput(request.held()));
    }
}
package net.officefloor.hq.app.person;

/** A validated hold body: whether the person is to be held. */
public record HoldInput(boolean held) {
}
package net.officefloor.hq.app.person;

/** The body of holding or releasing a person: true puts them on hold, false releases them. */
public record HoldRequest(Boolean held) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Puts the person on hold or releases them, refusing one already in that state. */
public class HoldPerson {
    public void hold(@Val HoldInput input, @Val Person person) throws InvalidPersonException {
        if (person.isHeld() == input.held()) {
            throw new InvalidPersonException(person.getName() + (input.held() ? " is already on hold." : " is not on hold."));
        }
        person.setHeld(input.held());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.HttpHeaderParameter;

/** Records PERSON_HELD or PERSON_RELEASED once the person is saved; the signed-in user arrives as X-User. */
public class AuditPersonHold {
    public void audit(@Val Person person, @HttpHeaderParameter("X-User") String user, Audit audit) {
        audit.record((person.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + person.getSheetId()
                + " by=" + (user == null ? "" : user.trim()) + " name=" + person.getName());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            PersonRepository repository, Out<Person> personOut) throws PersonNotFoundException {
        personOut.set(repository.findByIdAndSheetId(personId, sheetId.trim())
                .orElseThrow(() -> new PersonNotFoundException("No such person on this sheet.")));
    }
}
package net.officefloor.hq.app.person;

/** The audit line for a saved person: the event, sheet and user, then name and grade. */
public final class PersonAudit {
    private PersonAudit() {
    }

    public static String line(String event, Person person, String user) {
        return event + " sheet=" + person.getSheetId() + " by=" + (user == null ? "" : user.trim())
                + " name=" + person.getName() + " grade=" + person.getGrade();
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;

/** A person on a sheet, with a name and a grade (A, B or C); once retired, the date retired from; whether on hold. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

