package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the patron body, refusing one that names no one. */
public class ValidatePatron {
    public void validate(@RequestBody PatronRequest request, Out<PatronInput> patronOut) throws InvalidPersonException {
        if (request == null || request.patronId() == null) {
            throw new InvalidPersonException("Choose a patron.");
        }
        patronOut.set(new PatronInput(request.patronId()));
    }
}
EOF
cat > $P/AddPatron.java <<'EOF'
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Names another person on the sheet as the person's patron, refusing the person themselves or one already named. */
public class AddPatron {
    public void add(@Val PatronInput input, @Val Person person, PersonRepository repository,
            Out<AddedPatron> addedOut) throws InvalidPersonException {
        Person patron = repository.findByIdAndSheetId(input.patronId(), person.getSheetId())
                .orElseThrow(() -> new InvalidPersonException("No such person on this sheet."));
        if (patron.getId().equals(person.getId())) {
            throw new InvalidPersonException(person.getName() + " cannot be their own patron.");
        }
        if (!person.getPatronIds().add(patron.getId())) {
            throw new InvalidPersonException(patron.getName() + " is already a patron of " + person.getName() + ".");
        }
        addedOut.set(new AddedPatron(patron.getName()));
    }
}
EOF
cat > $P/AuditPatronAdded.java <<'EOF'
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.HttpHeaderParameter;

/** Records PATRON_ADDED once the person is saved; the signed-in user arrives as X-User. */
public class AuditPatronAdded {
    public void audit(@Val Person person, @Val AddedPatron patron, @HttpHeaderParameter("X-User") String user,
            Audit audit) {
        audit.record("PATRON_ADDED sheet=" + person.getSheetId() + " by=" + (user == null ? "" : user.trim())
                + " name=" + person.getName() + " patron=" + patron.name());
    }
}
EOF
